class Solution {
    public Node flipBinaryTree(Node root, Node leaf) {
        Node curr = leaf;
        Node p = curr.parent;
        curr.parent = null;
        while (curr != root) {
            if (curr.left != null) {
                curr.right = curr.left;
            }
            curr.left = p;
            Node gp = p.parent;
            if (p.left == curr) {
                p.left = null;
            } else if (p.right == curr) {
                p.right = null;
            }
            p.parent = curr;
            curr = p;
            p = gp;
        }
        return leaf;
    }
}

var flipBinaryTree = function(root, leaf) {
    let curr = leaf;
    let p = curr.parent;
    curr.parent = null;
    while (curr !== root) {
        if (curr.left) {
            curr.right = curr.left;
        }
        curr.left = p;
        const gp = p.parent;
        if (p.left === curr) {
            p.left = null;
        } else if (p.right === curr) {
            p.right = null;
        }
        p.parent = curr;
        curr = p;
        p = gp;
    }
    return leaf;
};
